class Route:
    def __init__(self, cells):
        self.cells = cells
        self.pos = 0

    def __iter__(self):
        return self

    def __next__(self):
        if self.pos >= len(self.cells):
            raise StopIteration
        cell = self.cells[self.pos]
        self.pos += 1
        return cell


print(list(Route([1, 2, 3])))
